const e = $input.first().json;
const msg = `Automation failure workflow=${e.workflow?.name ?? 'unknown'} execution=${e.execution?.id ?? 'n/a'} node=${e.trigger?.error?.node?.name ?? 'n/a'} message=${e.trigger?.error?.message ?? JSON.stringify(e)}`;
console.error(msg);
return [{ json: { alert: msg } }];
